import net.neoforged.neoforge.network.PacketDistributor;
import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import java.util.*;
final class ManeuverClientSmoke {
    private static int ticks,stage,at;private static volatile Throwable failure;private static BlockPos block;private static UUID focus,session;private static volatile SpaceTrajectory original;private static ManeuverNode node;
    static void tick(Minecraft mc,ServerSubLevel ship){
        if(stage==9)return;ticks++;if(failure!=null)throw new AssertionError("Maneuver server fixture",failure);if(ticks>1600)throw new AssertionError("Maneuver smoke timeout stage="+stage);
        if(stage==0){stage=1;at=ticks;server(mc,()->{var level=ship.getLevel();var cell=SpaceCells.get(level).forShip(ship.getUniqueId());focus=cell.id();var data=SpaceOrbitData.get(level.getServer());double radius=data.navigation(focus).orElseThrow().planet().radius(),r=radius+8000,mu=9.81*radius*radius,a=(r+1500000)/2;
            original=new SpaceTrajectory("around_planet:overworld",level.getGameTime(),new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(mu*(2/r-1/a)),0)),mu);data.put(focus,original);io.github.astelev.around_planet.compat.SpaceReentry.entered(level,focus,original.initial().position());dev.ryanhcode.sable.api.sublevel.SubLevelContainer.getContainer(level).physicsSystem().setPaused(true);
            var box=ship.getPlot().getBoundingBox();block=new BlockPos(box.minX(),box.minY()+2,box.minZ());level.setBlockAndUpdate(block,ManeuverRegistry.PLANNER.get().defaultBlockState());var p=level.players().getFirst();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK));p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);var result=level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));require(result==net.minecraft.world.InteractionResult.PASS,"Held item opened planner");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.TORCH));result=level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));require(result==net.minecraft.world.InteractionResult.PASS,"Offhand item opened planner");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);bindHelmet(ship);use(ship);});return;}
        if(ticks-at<35)return;
        if(stage==1){if(!(mc.screen instanceof OrbitMapScreen))return;var p=ManeuverClient.current();require(p!=null&&!p.session().equals(ManeuverPayload.NONE),"No server editor grant");session=p.session();var screen=(OrbitMapScreen)mc.screen;clickOrbit(screen);stage=2;at=ticks;return;}
        if(stage==2){var p=ManeuverClient.current();if(p==null||p.nodes().size()!=1)return;var fields=mc.screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).toList();require(fields.size()==4,"Planner axis fields missing");fields.get(0).setValue("25");fields.get(1).setValue("-5");fields.get(2).setValue("10");fields.get(3).setValue("40000");stage=3;at=ticks;return;}
        if(stage==3){var p=ManeuverClient.current();if(p.nodes().size()!=1||p.nodes().getFirst().prograde()!=25||p.nodes().getFirst().normal()!=-5||p.nodes().getFirst().radial()!=10)return;node=p.nodes().getFirst();require(node.tick()-ManeuverClient.now()>168000,"Distant node stayed inside the old time limit");var preview=preview((OrbitMapScreen)mc.screen);require(preview.segments().stream().anyMatch(ManeuverPreview.Segment::planned),"No post-burn curve");var finalCurve=preview.segments().getLast();require(finalCurve.points().getFirst().position().subtract(finalCurve.points().getLast().position()).length()<1e-5,"Bound post-burn curve did not close");var last=finalCurve.points().getLast();require(last.position().subtract(p.trajectory().at(last.tick()).position()).length()>10,"Preview ignored delta-v");inspect((OrbitMapScreen)mc.screen);snap(mc,"maneuver-editor-alpha31.png");server(mc,()->{var planner=(io.github.astelev.around_planet.maneuver.ManeuverPlannerBlockEntity)ship.getLevel().getBlockEntity(block);require(planner.warningSeconds()==40000,"Warning field did not save");require(ship.getLevel().getBlockState(block).getSignal(ship.getLevel(),block,Direction.UP)==15,"Warning field did not activate output");var data=SpaceOrbitData.get(mc.getSingleplayerServer());require(data.get(focus).orElseThrow().equals(original),"Planning executed a real burn");var copy=SpaceOrbitData.load(data.save(new net.minecraft.nbt.CompoundTag(),ship.getLevel().registryAccess()),ship.getLevel().registryAccess());require(copy.maneuvers(focus).equals(List.of(node)),"Plan did not persist");});mc.screen.onClose();stage=4;at=ticks;return;}
        if(stage==4){require(OrbitalHelmetHud.statsFrames>0&&OrbitalHelmetHud.plannerFrames>0,"Bound helmet lacks telemetry or maneuver countdown");snap(mc,"maneuver-helmet-alpha31.png");mc.setScreen(new OrbitMapScreen());stage=5;at=ticks;return;}
        if(stage==5){require(mc.screen.children().stream().noneMatch(EditBox.class::isInstance),"Ordinary map contains edit controls");require(ManeuverClient.current().nodes().size()==1,"Ordinary map lost saved node");require(!preview((OrbitMapScreen)mc.screen).nodes().isEmpty(),"Ordinary map lacks node marker");cameraControls((OrbitMapScreen)mc.screen);snap(mc,"maneuver-readonly-alpha31.png");PacketDistributor.sendToServer(new ManeuverPayload.Edit(session,999,false,new ManeuverNode(node.id(),node.tick(),999,0,0)));stage=6;at=ticks;return;}
        if(stage==6){snap(mc,"orbit-follow-alpha31.png");require(ManeuverClient.current().nodes().getFirst().prograde()==25,"Closed session accepted forged edit");mc.screen.onClose();stage=61;at=ticks;return;}
        if(stage==61){server(mc,()->use(ship));stage=7;at=ticks;return;}
        if(stage==7){if(!(mc.screen instanceof OrbitMapScreen screen))return;require(!ManeuverClient.current().session().equals(session),"Editor reused revoked session");var mark=preview(screen).nodes().getFirst();var point=project(screen,mark.position());screen.mouseClicked(point.x(),point.y(),0);screen.mouseReleased(point.x(),point.y(),0);var fields=screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).toList();require(Double.parseDouble(fields.get(0).getValue())==25,"Reopened planner lost delta-v");screen.children().stream().filter(Button.class::isInstance).map(Button.class::cast).filter(b->b.getMessage().getString().equals(net.minecraft.network.chat.Component.translatable("around_planet.maneuver.delete").getString())).findFirst().orElseThrow().onPress();stage=8;at=ticks;return;}
        if(stage==8){if(!ManeuverClient.current().nodes().isEmpty())return;mc.screen.onClose();stage=9;io.github.astelev.around_planet.AroundPlanet.LOGGER.info("MANEUVER_PLANNER PASS empty hands, server grant, orbit click, signed axes, predicted curve, persistence, read-only M map, revoked-session rejection, reopen and delete");mc.stop();}
    }
    private static void cameraControls(OrbitMapScreen screen){try{var f=OrbitMapScreen.class.getDeclaredField("camera");f.setAccessible(true);var camera=(OrbitCamera)f.get(screen);double x=screen.width/2.0,y=(screen.height-13)/2.0;screen.mouseDragged(x,y,1,35,-20);var pivot=camera.focus;require(pivot.length()>0,"Pan did not move world-space pivot");var before=project(screen,pivot);screen.mouseClicked(x,y,0);screen.mouseDragged(x+25,y+10,0,25,10);screen.mouseReleased(x+25,y+10,0);screen.mouseScrolled(x,y,0,2);var after=project(screen,pivot);require(Math.hypot(before.x()-after.x(),before.y()-after.y())<1e-6,"Orbit camera rotated/zoomed around planet instead of dragged pivot");f=OrbitMapScreen.class.getDeclaredField("followButton");f.setAccessible(true);var button=(Button)f.get(screen);button.onPress();require(camera.focus.length()>1000,"Follow button did not focus current space");var focused=project(screen,camera.focus);require(Math.hypot(focused.x()-x,focused.y()-y)<1e-6,"Follow focus is off-center");screen.mouseDragged(x,y,1,1,0);f=OrbitMapScreen.class.getDeclaredField("follow");f.setAccessible(true);require(!(Boolean)f.get(screen),"Manual pan did not disable follow");button.onPress();io.github.astelev.around_planet.AroundPlanet.LOGGER.info("ORBIT_CAMERA PASS world-space pan pivot, rotation, zoom and follow toggle");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void bindHelmet(ServerSubLevel ship){var level=ship.getLevel();var pos=block.east();level.setBlockAndUpdate(pos,io.github.astelev.around_planet.sensor.OrbitalSensorRegistry.BLOCK.get().defaultBlockState());((io.github.astelev.around_planet.sensor.OrbitalSensorBlockEntity)level.getBlockEntity(pos)).configure(OrbitalAttitude.Mode.MANEUVER,30);var p=level.players().getFirst();var helmet=new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("aeroengineering:engine_monitor_helmet")));p.setItemInHand(InteractionHand.MAIN_HAND,helmet);p.setShiftKeyDown(true);for(var target:List.of(pos,block))helmet.getItem().useOn(new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(target),Direction.UP,target,false)));require(io.github.astelev.around_planet.compat.AeroHelmetBridge.targets(helmet).containsAll(List.of(pos,block)),"Native helmet rejected planner or sensor binding");p.setShiftKeyDown(false);p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,helmet.copy());p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);}
    private static void inspect(OrbitMapScreen screen){try{var f=OrbitMapScreen.class.getDeclaredField("maneuvers");f.setAccessible(true);var layer=f.get(screen);var extrema=layer.getClass().getDeclaredField("apsides");extrema.setAccessible(true);var list=(java.util.List<OrbitInspection.Apsis>)extrema.get(layer);require(list.stream().anyMatch(OrbitInspection.Apsis::planned),"No planned apsides");var result=layer.getClass().getDeclaredField("result");result.setAccessible(true);require(result.get(layer)!=null,"Maneuver panel lacks forecast apsides");var visible=OrbitMapScreen.class.getDeclaredMethod("visible",SpaceVector.class);visible.setAccessible(true);var pick=layer.getClass().getDeclaredMethod("pick",double.class,double.class,boolean.class);pick.setAccessible(true);for(var a:list){if(!(Boolean)visible.invoke(screen,a.position()))continue;var xy=project(screen,a.position());var hit=pick.invoke(layer,xy.x()+2,xy.y()+2,false);require(hit!=null,"Apsis did not snap");var apsis=hit.getClass().getDeclaredMethod("apsis");apsis.setAccessible(true);require(apsis.invoke(hit)!=null,"Apsis picked as ordinary trajectory");return;}throw new AssertionError("No visible apsis for hover test");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void use(ServerSubLevel ship){var level=ship.getLevel();var p=level.players().getFirst();level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));}
    private static void clickOrbit(OrbitMapScreen screen){try{var visible=OrbitMapScreen.class.getDeclaredMethod("visible",SpaceVector.class);visible.setAccessible(true);var p=ManeuverClient.current();var curve=OrbitPlot.create(p.trajectory().at(ManeuverClient.now()),p.trajectory().mu(),SpaceHud.current().radius(),SpaceHud.current().returnAltitude(),false);for(double f:new double[]{.48,.45,.58,.32,.7,.85}){var point=p.trajectory().at(ManeuverClient.now()+(long)(curve.period()*20*f)).position();if(!(Boolean)visible.invoke(screen,point))continue;var xy=project(screen,point);screen.mouseClicked(xy.x(),xy.y(),0);screen.mouseReleased(xy.x(),xy.y(),0);return;}throw new AssertionError("No visible orbit hit target");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static OrbitCamera.Point project(OrbitMapScreen screen,SpaceVector p){try{var method=OrbitMapScreen.class.getDeclaredMethod("project",SpaceVector.class);method.setAccessible(true);return (OrbitCamera.Point)method.invoke(screen,p);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static ManeuverPreview preview(OrbitMapScreen screen){try{var f=OrbitMapScreen.class.getDeclaredField("maneuvers");f.setAccessible(true);var layer=f.get(screen);f=layer.getClass().getDeclaredField("preview");f.setAccessible(true);return (ManeuverPreview)f.get(layer);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void server(Minecraft mc,Runnable task){mc.getSingleplayerServer().execute(()->{try{task.run();}catch(Throwable e){failure=e;}});}
    private static void snap(Minecraft mc,String name){net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),m->{});}
    private static void require(boolean condition,String text){if(!condition)throw new AssertionError(text);}
}
